content.query:
let inputPer1M = {InputPrice:value};
let outputPer1M = {OutputPrice:value};
customMetrics
| where timestamp {TimeRange}
| where name in ("Prompt Tokens", "Completion Tokens")
| extend team = tostring(customDimensions["Team"])
| summarize prompt = sumif(valueSum, name == "Prompt Tokens"), completion = sumif(valueSum, name == "Completion Tokens") by team
| extend estimated_cost_usd = round(prompt / 1000000.0 * inputPer1M + completion / 1000000.0 * outputPer1M, 4)
| order by estimated_cost_usd desc
